.ds-button { display: inline-flex; min-block-size: 2.5rem; align-items: center; justify-content: center; gap: .5rem; border: 1px solid var(--rb-control-border, oklch(0.42 0.028 252)); border-radius: .625rem; padding: .4375rem .875rem; background: var(--rb-control, oklch(0.242 0.015 252)); color: var(--rb-danger, oklch(0.784 0.115 20)); font: 620 .8125rem/1.25 var(--font-geist-sans, "Geist Variable", ui-sans-serif, system-ui, sans-serif); text-align: center; cursor: pointer; transition: background-color 160ms ease-out, border-color 160ms ease-out; }
