.ds-landing-cta { display: inline-flex; align-items: center; gap: .5rem; border-radius: 9999px; padding: .75rem 2rem; background: #ffffff; color: #000000; font: 500 .875rem/1.25rem var(--font-geist-sans, "Geist Variable", ui-sans-serif, system-ui, sans-serif); text-decoration: none; transition: background-color 150ms cubic-bezier(.4,0,.2,1); }
.ds-landing-cta svg { flex: none; transition: transform 150ms cubic-bezier(.4,0,.2,1); }
.ds-landing-cta:hover { background: #e5e5e5; }
.ds-landing-cta:hover svg { transform: translateX(.125rem); }
.ds-landing-cta:focus-visible { outline: 2px solid #60a5fa; outline-offset: 3px; border-radius: 9999px; }
@media (prefers-reduced-motion: reduce) { .ds-button, .ds-landing-cta, .ds-landing-cta svg, .ds-nav-item, .ds-slot select { transition: none; } }

.ds-field { display: grid; gap: .375rem; min-inline-size: 0; color: var(--rb-ink, oklch(0.957 0.009 252)); font: 560 .8125rem/1.5 var(--font-geist-sans, "Geist Variable", ui-sans-serif, system-ui, sans-serif); }
.ds-field-input { box-sizing: border-box; min-inline-size: 0; min-block-size: 2.625rem; border: 1px solid var(--rb-control-border, oklch(0.42 0.028 252)); border-radius: .5rem; padding: .5rem .75rem; background: var(--rb-control, oklch(0.242 0.015 252)); color: var(--rb-ink, oklch(0.957 0.009 252)); font: 400 .875rem/1.5 var(--font-geist-mono, "Geist Mono Variable", ui-monospace, SFMono-Regular, monospace); }
.ds-field-input::placeholder { color: var(--rb-ink-muted, oklch(0.739 0.021 252)); }
.ds-field-input:hover { border-color: var(--rb-accent, oklch(0.789 0.108 248)); }
.ds-field-input[aria-invalid="true"] { border-color: var(--rb-danger, oklch(0.784 0.115 20)); }
.ds-field-input:focus-visible { outline: 2px solid var(--rb-accent, oklch(0.789 0.108 248)); outline-offset: 2px; border-radius: .4375rem; }

.ds-panel { min-inline-size: 0; border: 1px solid var(--rb-border, oklch(0.31 0.017 252)); border-radius: 1rem; padding: 1.125rem; background: var(--rb-surface-raised, oklch(0.189 0.01 252)); color: var(--rb-ink, oklch(0.957 0.009 252)); }
.ds-panel h3 { margin: 0; font: 700 1.0625rem/1.5 var(--font-manrope, "Manrope Variable", ui-sans-serif, system-ui, sans-serif); letter-spacing: -.022em; }
.ds-panel p { margin: .625rem 0 0; color: var(--rb-ink-muted, oklch(0.739 0.021 252)); font: 400 .875rem/1.55 var(--font-geist-sans, "Geist Variable", ui-sans-serif, system-ui, sans-serif); }
@media (min-width: 70rem) { .ds-panel { padding: 1.5rem; } }

.ds-nav-item { display: flex; align-items: center; gap: .75rem; border: 1px solid transparent; border-radius: .75rem; padding: .5rem .75rem; color: var(--rb-ink-muted, oklch(0.739 0.021 252)); font: 500 .875rem/1.25rem var(--font-geist-sans, "Geist Variable", ui-sans-serif, system-ui, sans-serif); text-decoration: none; transition: color 150ms cubic-bezier(.4,0,.2,1), background-color 150ms cubic-bezier(.4,0,.2,1); }
.ds-nav-item:is(:hover, [aria-current]) { background: var(--rb-surface-raised, oklch(0.189 0.01 252)); color: var(--rb-ink, oklch(0.957 0.009 252)); }
.ds-nav-item[aria-current] { border-color: var(--rb-border, oklch(0.31 0.017 252)); }
.ds-nav-item[aria-current] svg { color: var(--rb-accent, oklch(0.789 0.108 248)); }
.ds-nav-item:focus-visible { outline: 2px solid var(--rb-accent, oklch(0.789 0.108 248)); outline-offset: 2px; border-radius: .4375rem; }
@media (prefers-reduced-motion: reduce) { .ds-button, .ds-landing-cta, .ds-landing-cta svg, .ds-nav-item, .ds-slot select { transition: none; } }

.ds-network-group { display: flex; flex-wrap: wrap; gap: .5rem; }
.ds-network { display: inline-flex; align-items: center; border: 1px solid var(--ds-line); border-radius: 999px; padding: .125rem .5rem; background: var(--ds-fill); color: var(--ds-ink); font: 560 .75rem/1.35 var(--font-geist-sans, "Geist Variable", ui-sans-serif, system-ui, sans-serif); }
.ds-network[data-role="automation"] { --ds-line: var(--rb-automation-line, oklch(0.436 0.069 290)); --ds-fill: var(--rb-automation-tint, oklch(0.259 0.047 290)); --ds-ink: var(--rb-automation, oklch(0.835 0.083 290)); }
.ds-network[data-role="funds"] { --ds-line: var(--rb-funds-line, oklch(0.437 0.061 175)); --ds-fill: var(--rb-funds-tint, oklch(0.255 0.038 175)); --ds-ink: var(--rb-funds, oklch(0.817 0.106 175)); }

.ds-status-group { display: flex; flex-wrap: wrap; gap: .5rem; }
.ds-status { display: inline-flex; align-items: center; gap: .3125rem; border: 1px solid color-mix(in oklch, var(--ds-status) 31%, var(--rb-control, oklch(0.242 0.015 252))); border-radius: .375rem; padding: .15rem .5rem; background: color-mix(in oklch, var(--ds-status) 10%, var(--rb-control, oklch(0.242 0.015 252))); color: var(--ds-status); font: 550 .75rem/1.3 var(--font-geist-sans, "Geist Variable", ui-sans-serif, system-ui, sans-serif); }
.ds-status::before { content: ""; flex: none; width: .375rem; height: .375rem; border-radius: 50%; background: currentColor; }
.ds-status[data-status="active"] { --ds-status: var(--rb-status-active, oklch(0.812 0.113 151)); }
.ds-status[data-status="paused"] { --ds-status: var(--rb-status-paused, oklch(0.831 0.113 79)); }
.ds-status[data-status="silent"] { --ds-status: var(--rb-danger, oklch(0.784 0.115 20)); }

.ds-slot-group { display: flex; flex-wrap: wrap; gap: .5rem; }
.ds-slot { position: relative; display: inline-block; max-inline-size: 100%; border-radius: .5rem; color: var(--rb-accent, oklch(0.789 0.108 248)); }
.ds-slot::after { content: ""; position: absolute; inset-inline-end: .875rem; inset-block-start: calc(50% - .25rem); inline-size: .375rem; block-size: .375rem; border: solid currentColor; border-width: 0 1.5px 1.5px 0; transform: rotate(45deg); pointer-events: none; }
.ds-slot select { appearance: none; display: block; inline-size: 100%; min-block-size: 2.5rem; field-sizing: content; border: 1px dashed oklch(0.494 0.065 249); border-radius: inherit; padding: .4375rem 1.875rem .4375rem .6875rem; background: oklch(0.255 0.028 249); color: inherit; font: 580 .875rem/1.25 var(--font-geist-sans, "Geist Variable", ui-sans-serif, system-ui, sans-serif); cursor: pointer; transition: background-color 160ms ease-out, border-color 160ms ease-out; }
.ds-slot[data-filled="true"] select, .ds-slot:has(select option:not([value=""]):checked) select { border-style: solid; border-color: oklch(.487 .066 249); background: var(--rb-accent-tint, oklch(0.286 0.054 249)); color: var(--rb-ink, oklch(0.957 0.009 252)); }
.ds-slot select:hover { border-color: var(--rb-accent, oklch(0.789 0.108 248)); background: var(--rb-accent-tint, oklch(0.286 0.054 249)); }
.ds-slot select[aria-invalid="true"] { border-color: var(--rb-danger, oklch(0.784 0.115 20)); }
.ds-slot option { background: var(--rb-surface-raised, oklch(0.189 0.01 252)); color: var(--rb-ink, oklch(0.957 0.009 252)); }
.ds-slot select:focus-visible { outline: 2px solid var(--rb-accent, oklch(0.789 0.108 248)); outline-offset: 2px; border-radius: .4375rem; }
